package com.forgebuild.engine.ui.icons

import androidx.compose.ui.graphics.vector.ImageVector

/**
 * Material Symbols icon set bundled locally (offline-friendly, no runtime font).
 * Icon glyphs are generated by tools/gen_icons.py into EngineIconsGenerated.kt.
 */
object EngineIcons {
    val Bolt: ImageVector get() = EngineIconsGenerated.Bolt
    val Settings: ImageVector get() = EngineIconsGenerated.Settings
    val Add: ImageVector get() = EngineIconsGenerated.Add
    val Home: ImageVector get() = EngineIconsGenerated.Home
    val Search: ImageVector get() = EngineIconsGenerated.Search
    val ArrowBack: ImageVector get() = EngineIconsGenerated.ArrowBack
    val DesktopWindows: ImageVector get() = EngineIconsGenerated.DesktopWindows
    val Alarm: ImageVector get() = EngineIconsGenerated.Alarm
    val Schedule: ImageVector get() = EngineIconsGenerated.Schedule
    val PlayArrow: ImageVector get() = EngineIconsGenerated.PlayArrow
    val Pause: ImageVector get() = EngineIconsGenerated.Pause
    val Stop: ImageVector get() = EngineIconsGenerated.Stop
    val VolumeUp: ImageVector get() = EngineIconsGenerated.VolumeUp
    val Notifications: ImageVector get() = EngineIconsGenerated.Notifications
    val MusicNote: ImageVector get() = EngineIconsGenerated.MusicNote
    val Headphones: ImageVector get() = EngineIconsGenerated.Headphones
    val Edit: ImageVector get() = EngineIconsGenerated.Edit
    val Delete: ImageVector get() = EngineIconsGenerated.Delete
    val Check: ImageVector get() = EngineIconsGenerated.Check
    val CheckCircle: ImageVector get() = EngineIconsGenerated.CheckCircle
    val Info: ImageVector get() = EngineIconsGenerated.Info
    val Refresh: ImageVector get() = EngineIconsGenerated.Refresh
    val Warning: ImageVector get() = EngineIconsGenerated.Warning
}
